/*
This node creates messages to indicate the current error state of a cutter.
Only SY messages that changed from or changed to an error state are incoming. (See CMD Store node)
If SY = 3 a new message with error code, parameters, metadata will be published to the MQTT Broker.
If SY =! 3 a message with erro code = 0 will be published to the MQTT Broker.

he last number in the hexadecimal code of ErrorNumber defines the error 
category. There are four categories:
1: User information (not an Error, cutter will not stop or go offline)
2: Warning (There may be a problem, but the cutter will not stop or go offline)
3: Failure (Cutter switches to stopped mode. The user can solve the problem 
and go online afterwards)
4: Fatal Error (Cutter switches to stopped mode, the user must shutdown 
cutter)
*/
const cutter_id = msg.deviceId.slice(0, -2)  // extract base cutter id without beam (-a / -b)
let SY = parseInt(msg.SY, 10);

if (SY === 3) {
    let error_code = msg.ER[0];
    let category = parseInt(error_code.slice(-1), 10);  // Parse the category (last digit of error code)
    let index1 = msg.ER?.[1] ?? null;
    let index2 = msg.ER?.[2] ?? null;

    msg.payload = {
        "device_id": cutter_id,
        "timestamp": msg.timestamp,
        "error_code": error_code,
        "category": category,
        "index1": index1,
        "index2": index2
    }
}
else {
    msg.payload = {
        "device_id": cutter_id,
        "timestamp": msg.timestamp,
        "error_code": "no error",
        "category": 0,
        "index1": null,
        "index2": null
    }
}

msg.topic = `polipol/3000/szw/krt/${cutter_id}/error`;

return msg;
